<?php
require_once __DIR__.'/../plugins/fpdf/fpdf.php';

final class AppuElectronicDocumentPdf extends FPDF {
 private array $company; private array $doc; private string $label; private string $logo;
 function __construct(array $company,array $doc,string $label,string $logo){parent::__construct('P','mm','A4');$this->company=$company;$this->doc=$doc;$this->label=$label;$this->logo=$logo;$this->SetMargins(12,12,12);$this->SetAutoPageBreak(true,22);}
 private function t($v):string{$s=(string)$v;return iconv('UTF-8','windows-1252//TRANSLIT',$s)?:$s;}
 function Header():void{
  if($this->logo&&is_file($this->logo))$this->Image($this->logo,12,12,34);
  $this->SetXY(49,12);$this->SetFont('Arial','B',12);$this->Cell(94,6,$this->t($this->company['legal_name']?:'APPU'),0,1);$this->SetX(49);$this->SetFont('Arial','',8);$this->MultiCell(94,4,$this->t($this->company['address']?:'Domicilio fiscal no configurado'));
  $loc=implode(' - ',array_filter([$this->company['district']??'',$this->company['province']??'',$this->company['department']??'']));if($loc){$this->SetX(49);$this->Cell(94,4,$this->t($loc));}
  $this->SetXY(146,12);$this->SetDrawColor(35,75,120);$this->SetLineWidth(.45);$this->SetFont('Arial','B',10);$this->Cell(52,8,'RUC: '.$this->t($this->company['tax_id']),'LTR',1,'C');$this->SetX(146);$this->Cell(52,8,$this->t($this->label.' ELECTRONICA'),'LR',1,'C');$this->SetX(146);$this->SetFont('Arial','B',12);$this->Cell(52,9,$this->t($this->doc['series'].'-'.$this->doc['number']),'LBR',1,'C');$this->Ln(7);
 }
 function Footer():void{$this->SetY(-17);$this->SetFont('Arial','I',7.5);$this->SetTextColor(80,80,80);$this->MultiCell(0,4,$this->t('Esta es una representación impresa del comprobante electrónico. La validez tributaria se acredita con el XML y la respuesta de SUNAT.'),0,'C');$this->Cell(0,4,$this->t('Página '.$this->PageNo()),0,0,'C');}
 private function field(string $a,string $b,string $c='',string $d=''):void{$this->SetFont('Arial','B',8);$this->Cell(29,6,$this->t($a.':'));$this->SetFont('Arial','',8);$this->Cell(79,6,$this->t($b));if($c){$this->SetFont('Arial','B',8);$this->Cell(23,6,$this->t($c.':'));$this->SetFont('Arial','',8);$this->Cell(57,6,$this->t($d));}$this->Ln();}
 function render(array $lines,array $taxes,?array $sunat):void{
  $this->AddPage();$status=$sunat['status']??'draft';$names=['accepted'=>'ACEPTADO POR SUNAT','observed'=>'ACEPTADO CON OBSERVACIONES','rejected'=>'RECHAZADO POR SUNAT','processing'=>'EN PROCESO','technical_error'=>'ERROR TECNICO','draft'=>'PENDIENTE DE ENVIO','simulation'=>'SIMULACION QA - NO VALIDO'];
  $this->SetFillColor(232,244,238);$this->SetTextColor(25,80,55);$this->SetFont('Arial','B',8);$this->Cell(0,6,$this->t('Estado SUNAT: '.($names[$status]??strtoupper($status))),1,1,'C',true);$this->SetTextColor(0);$this->Ln(3);
  $this->field('Fecha de emisión',date('d/m/Y',strtotime($this->doc['date'])),'Moneda',$this->doc['currency_label']);$this->field('Cliente',$this->doc['name'],'RUC / DNI',$this->doc['ruc']);$this->field('Dirección',$this->doc['address']?:'No consignada','Forma de pago',$this->doc['payment_label']);$this->Ln(3);
  $w=[12,22,20,77,28,29];$h=['Cant.','Unidad','Código','Descripción','V. unitario','Importe'];$this->SetFillColor(35,75,120);$this->SetTextColor(255);$this->SetFont('Arial','B',8);foreach($h as $i=>$v)$this->Cell($w[$i],7,$this->t($v),1,0,'C',true);$this->Ln();$this->SetTextColor(0);$this->SetFont('Arial','',7.5);
  foreach($lines as $line){if($this->GetY()>250)$this->AddPage();$desc=trim((string)(($line['item_description']??'')?:($line['item_name']??'')));$y=$this->GetY();$height=max(7,ceil($this->GetStringWidth($this->t($desc))/74)*4);$x=$this->GetX();$vals=[number_format((float)$line['item_quantity'],2),$line['sunat_unit_code']?:'NIU',$line['item_code'],'',number_format((float)$line['item_unit_price'],2),number_format((float)$line['item_quantity']*(float)$line['item_unit_price'],2)];foreach($vals as $i=>$v){$this->SetXY($x+array_sum(array_slice($w,0,$i)),$y);if($i===3)$this->MultiCell($w[$i],4,$this->t($desc),1);else $this->Cell($w[$i],$height,$this->t($v),1,0,$i===0||$i>3?'R':'C');}$this->SetY($y+$height);}
  $this->Ln(4);$this->SetX(112);foreach($taxes as $k=>$v){$this->Cell(52,6,$this->t($k),1,0,'R');$this->Cell(34,6,$this->t($this->doc['currency_symbol'].' '.number_format($v,2)),1,1,'R');$this->SetX(112);}$this->SetFont('Arial','B',9);$this->Cell(52,7,'IMPORTE TOTAL',1,0,'R');$this->Cell(34,7,$this->t($this->doc['currency_symbol'].' '.number_format($this->doc['total_net'],2)),1,1,'R');if($sunat){$this->Ln(4);$this->SetFont('Arial','',7);$this->MultiCell(0,4,$this->t('Respuesta SUNAT: '.trim(($sunat['sunat_code']??'').' '.($sunat['sunat_description']??''))));}
 }
}

function appu_load_electronic_document(PDO $pdo,string $type,int $id):array{
 $defs=['invoice'=>['tbl_invoice','tbl_invoice_detail','invoice_id','FACTURA'],'receipt'=>['tbl_receipt','tbl_receipt_detail','receipt_id','BOLETA DE VENTA'],'credit-note'=>['tbl_credit_note','tbl_credit_note_detail','credit_note_id','NOTA DE CREDITO']];if(!isset($defs[$type])||$id<1)throw new InvalidArgumentException('El documento solicitado no es válido.');[$table,$detail,$foreign,$label]=$defs[$type];
 $q=$pdo->prepare("SELECT * FROM $table WHERE id=?");$q->execute([$id]);$document=$q->fetch();if(!$document)throw new RuntimeException('No se encontró el documento.');$q=$pdo->prepare("SELECT d.*,COALESCE(p.sunat_unit_code,'NIU') sunat_unit_code,COALESCE(p.tax_affectation_code,'10') tax_affectation_code FROM $detail d LEFT JOIN tbl_product p ON p.id=d.item_id WHERE d.$foreign=? ORDER BY d.id");$q->execute([$id]);$lines=$q->fetchAll();$company=$pdo->query('SELECT * FROM tbl_company_settings WHERE id=1')->fetch()?:[];$sunat=null;try{$q=$pdo->prepare('SELECT status,sunat_code,sunat_description FROM tbl_sunat_document WHERE source_type=? AND source_id=?');$q->execute([$type,$id]);$sunat=$q->fetch()?:null;}catch(Throwable $e){}
 $taxes=['Op. gravadas'=>0.0,'Op. exoneradas'=>0.0,'Op. inafectas'=>0.0];foreach($lines as $line){$v=$line['item_quantity']*$line['item_unit_price'];$c=(string)$line['tax_affectation_code'];$taxes[$c==='10'?'Op. gravadas':($c==='20'?'Op. exoneradas':'Op. inafectas')]+=$v;}$taxes['IGV']=(float)$document['total_tax'];if((float)$document['discount_value'])$taxes['Descuento']=(float)$document['discount_value'];$taxes=array_filter($taxes,fn($v)=>abs($v)>.0001);$usd=in_array(strtoupper($document['currency']),['ME','USD'],true);$document['currency_label']=$usd?'DÓLARES AMERICANOS':'SOLES';$document['currency_symbol']=$usd?'US$':'S/';$days=(int)$document['payment_days'];$document['payment_label']=$days?'Crédito a '.$days.' días':'Contado';return compact('company','document','lines','sunat','taxes','label');
}
